独立参考解答：令 `newColor` 为替换后的颜色。用栈做四邻域深度优先搜索；一个点入栈时立刻改色，以防重复入栈，也避免原色等于新色时无法终止。

```c
typedef struct { int r, c; } Point;

Status Recolor(int g[MAXM][MAXN], int m, int n,
               int i0, int j0, int newColor) {
    if (i0 < 0 || i0 >= m || j0 < 0 || j0 >= n ||
        newColor < 0 || newColor > K) return ERROR;
    int old = g[i0][j0];
    if (old == newColor) return OK;

    Stack S; InitStack(&S);       // 容量至少为 m*n
    g[i0][j0] = newColor;
    Push(&S, (Point){i0, j0});
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    while (!StackEmpty(S)) {
        Point p; Pop(&S, &p);
        for (int d = 0; d < 4; ++d) {
            int r = p.r + dr[d], c = p.c + dc[d];
            if (0 <= r && r < m && 0 <= c && c < n && g[r][c] == old) {
                g[r][c] = newColor;
                Push(&S, (Point){r, c});
            }
        }
    }
    return OK;
}
```

算法只改变起点所在的四连通同色区域；最坏时间和栈空间均为 O(mn)。

